const chat46OldBoss=bossText;
bossText=function(b,stage){if(stage===0&&(!b.special||Math.random()<.7))return chat46Pick(1,b);if(stage>0&&Math.random()<.65)return chat46Pick(3,b);return chat46OldBoss(b,stage)};
function chat46Npc(line){chat46Add('dialogue',line.speaker,chat46Translate(line.text));}
const chat46OldNote=note;note=function(t){chat46Add('system','',chat46Translate(t));chat46SeenState=s;chat46SeenMsg=String(t);return chat46OldNote(t)};
const chat46OldReward=reward;reward=function(g,x){let lv=s.level,paid=chat46OldReward(g,x);if(s.level!==lv){chat46Add('system','',hubLabel('Levelaufstieg: ','Level up: ','Новый уровень: ')+lv+' → '+s.level);chat46SeenState=s;chat46SeenMsg=String(msg)}return paid};
function chat46Finish(b){if(b.win){chat46Add('system','',hubLabel('Kampf gewonnen','Battle won','Бой выигран')+' · '+b.o.enemy+(b.cashPaid!=null?' · $'+fmt(b.cashPaid):'')+(b.xpPaid!=null?' · '+fmt(b.xpPaid)+' XP':''));}else chat46Add('system','',hubLabel('Kampf verloren','Battle lost','Бой проигран')+' · '+b.o.enemy);
 if(b.materialDrop)chat46Add('system','',materialName(b.materialDrop.id)+' ×'+b.materialDrop.qty);
 let n=(Number(s.chat46Battles)||0)+1;s.chat46Battles=n;
 if(n%4===0&&Date.now()-(s.chat46LastPM||0)>=180000){let row=CHAT46_PM[(Math.floor(n/4)-1)%CHAT46_PM.length];chat46Add('private',row[0],hubLabel(...row.slice(1)));s.chat46LastPM=Date.now();s.chat46Unread=(s.chat46Unread||0)+1;}
}
function chat46Open(){chat46FilterKey='all';s.chat46Unread=0;chat46Stamp='';$('modal').hidden=false;$('modal').innerHTML='<div class="sheet kwChatSheet" id="kwChatSheet"></div>';chat46Draw();save();}
function chat46Filter(k){if(!['all','dialogue','combat','system','private'].includes(k))return;chat46FilterKey=k;chat46Stamp='';chat46Draw();}
function chat46Draw(){let el=$('kwChatSheet');if(!el||$('modal').hidden)return;let a=chat46Entries(),stamp=chat46FilterKey+'|'+s.lang+'|'+a.length+'|'+(a.at(-1)?.at||0)+'|'+(a.at(-1)?.t||'');if(stamp===chat46Stamp)return;chat46Stamp=stamp;
 let opts=[['all',hubLabel('Alles','All','Всё')],['dialogue',hubLabel('Dialoge','Dialogue','Диалоги')],['combat',hubLabel('Kampf','Combat','Бой')],['system',hubLabel('System','System','Система')],['private',hubLabel('Privat','Private','Личные')]];
 let filtered=a.filter(r=>chat46FilterKey==='all'||r.kind===chat46FilterKey).slice(-150).reverse();let lang=s.lang==='ru'?'ru-RU':s.lang==='en'?'en-GB':'de-DE';
 el.innerHTML=`<div class="row"><h3>${hubLabel('Hinterhof-Funk','Backyard chat','Дворовой чат')}</h3><button class="close" onclick="closeItem()">×</button></div><small>${hubLabel('Lokales Spielprotokoll · NPC-Nachrichten','Local game log · NPC messages','Локальный журнал · сообщения NPC')}</small><div class="kwChatFilters">${opts.map(([k,n])=>`<button class="${k===chat46FilterKey?'active':''}" onclick="chat46Filter('${k}')">${n}</button>`).join('')}</div><div class="kwChatHistory">${filtered.map(r=>{let who=r.who||opts.find(o=>o[0]===r.kind)?.[1]||'';return `<div class="kwChatLine ${['combat','system','dialogue','private'].includes(r.kind)?r.kind:'system'}"><div><b>${logEscape(who)}${r.kind==='private'?' · '+hubLabel('Privat','Private','Личные'):''}</b><small>${new Date(r.at).toLocaleTimeString(lang,{hour:'2-digit',minute:'2-digit'})}</small></div><span>${logEscape(r.t)}</span></div>`}).join('')||`<p class="muted">${hubLabel('Noch keine Nachrichten.','No messages yet.','Сообщений пока нет.')}</p>`}</div><small>${hubLabel('Neueste zuerst · letzte 150 pro Ansicht','Newest first · last 150 per view','Сначала новые · последние 150 в разделе')}</small><button onclick="closeItem()">${hubLabel('Schließen','Close','Закрыть')}</button>`;
}
function chat46Sync(){if(chat46SeenState!==s){chat46SeenState=s;chat46SeenMsg=String(msg||'')}else if(String(msg||'')!==chat46SeenMsg){chat46SeenMsg=String(msg||'');if(msg)chat46Add('system','',chat46Translate(msg))}let a=chat46Entries(),last=a.at(-1),toast=document.querySelector('#screen .toast');if(toast){let button=toast.querySelector('.kwChatButton');if(!button){toast.innerHTML='<button class="kwChatButton" onclick="chat46Open()"><b></b><span></span></button>';button=toast.firstElementChild;}let title=hubLabel('Chat','Chat','Чат')+(s.chat46Unread?' ('+s.chat46Unread+')':'')+' ›',text=last?((last.who?last.who+': ':'')+last.t):hubLabel('Spielprotokoll öffnen','Open game log','Открыть журнал');if(button.firstElementChild.textContent!==title)button.firstElementChild.textContent=title;if(button.lastElementChild.textContent!==text)button.lastElementChild.textContent=text;}chat46Draw();}

const world45BattleLog=battleLog;
battleLog=function(b,t,kind='system'){world45BattleLog(b,t,kind);if(kind==='speech'){b.dialogue45??={};let line=chat46Translate(b.warning||String(t));b.dialogue45.enemy={text:line,until:Date.now()+3600};chat46Add('dialogue',b.o.enemy,line)}else chat46Add('combat','',chat46Translate(t));};
function world45PlayerSpeech(b,text){b.dialogue45??={};b.dialogue45.player={text,until:Date.now()+3600};world45BattleLog(b,profileName()+': „'+text+'“','speech');chat46Add('dialogue',profileName(),text)}
function world45Bubble(doc,text,cls=''){let el=doc.createElement('div');el.className='kwSpeech '+cls;el.setAttribute('role','status');el.textContent=typeof replaceText==='function'?replaceText(text):text;return el}
function world45Dialogues(clone){const doc=clone.ownerDocument,sub=$('npcSubtitle');if(page==='Kampf'&&battle){clone.querySelector('.raidWarning')?.remove();for(let [k,selector] of [['player','.fighter:not(.foe)'],['enemy','.fighter.foe']]){let d=battle.dialogue45?.[k],f=clone.querySelector(selector);if(d&&f&&d.until>Date.now())f.append(world45Bubble(doc,d.text,'fightSpeech'))}return}
 if(!sub||sub.hidden||!sub.textContent)return;let text=sub.textContent.split(' · ').slice(1).join(' · ')||sub.textContent;let selector=page==='Händler'?'.shophead':page==='Kiosk'?'.kiosk':page==='Pfandspiel'?'.pfHost':null;
 if(selector){let anchor=clone.querySelector(selector);if(anchor){anchor.classList.add('dialogueAnchor');anchor.append(world45Bubble(doc,text,'npcSpeech'));}return}
 if(page==='Missionen'){let anchor=clone.querySelector('.missionScene');if(anchor){let row=doc.createElement('div');row.className='questDialogue';let img=doc.createElement('img');img.src=WORLD45_NPC[0];img.alt='Mopowitsch';row.append(img,world45Bubble(doc,text,'questSpeech'));anchor.before(row)}}
}

